# package-windows.ps1 — package the Windows build (must run on Windows)
#
#   1. nsh package --target windows: .nsh\out\NSPtoNUP\ (NSPtoNUP.exe + nsh\)
#   2. copy tools\windows-<arch>\ into NSPtoNUP\tools\
#   3. repackage as .nsh\out\NSPtoNUP-windows-<arch>.zip
#
# The Inno Setup installer generated by nsh doesn't include the tools, so it isn't published for now; only the zip is.
# First run scripts/fetch-tools.sh in Git Bash (MSYS2 MINGW64) to prepare the tools. Untested (this release is only verified on macOS).

$ErrorActionPreference = "Stop"
$Root = Split-Path -Parent $PSScriptRoot
$Out = Join-Path $Root ".nsh\out"
$Arch = if ($env:PROCESSOR_ARCHITECTURE -eq "ARM64") { "arm64" } else { "x64" }
$Tools = Join-Path $Root "tools\windows-$Arch"

foreach ($tool in "nxpatch", "nup") {
  if (-not (Test-Path (Join-Path $Tools "$tool.exe"))) { throw "Missing $Tools\$tool.exe; run scripts/fetch-tools.sh first" }
}

Write-Host "==> nsh package (Windows $Arch)"
Set-Location $Root
$App = Join-Path $Out "NSPtoNUP"
if (Test-Path $App) { Remove-Item -Recurse -Force $App }
nsh package App.tsx --target windows --out $Out
if (-not (Test-Path $App)) { throw "$App was not created" }

Write-Host "==> Copying tools to NSPtoNUP\tools\"
New-Item -ItemType Directory -Force (Join-Path $App "tools") | Out-Null
Copy-Item (Join-Path $Tools "*.exe") (Join-Path $App "tools")

$Zip = Join-Path $Out "NSPtoNUP-windows-$Arch.zip"
if (Test-Path $Zip) { Remove-Item -Force $Zip }
Compress-Archive -Path $App -DestinationPath $Zip
Write-Host "==> Done: $Zip"
